WITH web_events_by_session AS (SELECT session_id, COUNT(DISTINCT duration_sec) AS unique_event_types, SUM(duration_sec) AS total_duration_sec FROM web_events WHERE session_id IN (5, 19) GROUP BY session_id) SELECT s.browser, webs.unique_event_types, webs.total_duration_sec FROM sessions s INNER JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.total_duration_sec >= 900 ORDER BY webs.unique_event_types DESC, total_duration_sec DESC;
